import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { cn } from "@/lib/utils";
import {
  Facebook,
  Instagram,
  Linkedin,
  Plus,
  Twitter,
  Youtube,
} from "lucide-react";
import Link from "next/link";

type FooterLink = { label: string; href: string };
type FooterGroup = { heading?: string; links: FooterLink[] };
type FooterColumn = { title: string; groups: FooterGroup[] };

const columns: FooterColumn[] = [
  {
    title: "Product",
    groups: [
      {
        heading: "Components",
        links: [
          { label: "All Components", href: "/docs" },
          { label: "Forms", href: "/docs/forms" },
          { label: "Data Display", href: "/docs/data-display" },
          { label: "Navigation", href: "/docs/navigation" },
          { label: "Feedback", href: "/docs/feedback" },
        ],
      },
      {
        heading: "Blocks",
        links: [
          { label: "Hero Sections", href: "/blocks/heroes" },
          { label: "Feature Sections", href: "/blocks/features" },
          { label: "Footers", href: "/blocks/footers" },
        ],
      },
    ],
  },
  {
    title: "Resources",
    groups: [
      {
        heading: "Learn",
        links: [
          { label: "Documentation", href: "/docs" },
          { label: "Theming Guide", href: "/docs/theming" },
          { label: "Dark Mode", href: "/docs/dark-mode" },
        ],
      },
      {
        heading: "Examples",
        links: [
          { label: "Dashboard", href: "/examples/dashboard" },
          { label: "Cards", href: "/examples/cards" },
          { label: "Playground", href: "/examples/playground" },
        ],
      },
    ],
  },
  {
    title: "About",
    groups: [
      {
        links: [
          { label: "Pricing", href: "/pricing" },
          { label: "Blog", href: "/blog" },
          { label: "Support", href: "/support" },
          { label: "Contact", href: "/contact" },
          { label: "Careers", href: "/careers" },
        ],
      },
    ],
  },
  {
    title: "Developers",
    groups: [
      {
        links: [
          { label: "CLI", href: "/docs/cli" },
          { label: "Registry API", href: "/docs/registry-api" },
          { label: "GitHub", href: "https://github.com" },
        ],
      },
    ],
  },
];

const socialLinks = [
  { icon: Facebook, href: "https://facebook.com", label: "Facebook" },
  { icon: Instagram, href: "https://instagram.com", label: "Instagram" },
  { icon: Twitter, href: "https://x.com", label: "X" },
  { icon: Youtube, href: "https://youtube.com", label: "YouTube" },
  { icon: Linkedin, href: "https://linkedin.com", label: "LinkedIn" },
];

const legalLinks: FooterLink[] = [
  { label: "Privacy Policy", href: "/privacy" },
  { label: "Terms of Service", href: "/terms" },
];

const linkClass =
  "text-sm text-muted-foreground transition-colors hover:text-foreground";

export const Footer = () => {
  return (
    <footer
      className="relative flex w-full flex-col overflow-hidden bg-background px-3 pt-8 pb-4 text-foreground xl:px-10 xl:pt-25"
      role="contentinfo"
      aria-labelledby="footer-heading"
    >
      <h2 id="footer-heading" className="sr-only">
        Footer
      </h2>

      <div className="relative z-20 flex flex-col justify-between xl:flex-row xl:gap-40">
        {/* Left column — socials + blurb */}
        <div className="flex flex-col">
          <div className="flex w-full justify-center lg:justify-normal gap-5">
            {socialLinks.map((social) => (
              <Link
                key={social.label}
                href={social.href}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={social.label}
                className="text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:text-foreground focus-visible:outline-none"
              >
                <social.icon className="size-5 sm:size-7 xl:size-5" />
              </Link>
            ))}
          </div>

          {/* Mobile accordions */}
          <div className="mt-8 flex flex-col xl:hidden">
            <Accordion
              className="flex w-full flex-col divide-y divide-foreground/15"
              transition={{ duration: 0.3, ease: "easeInOut" }}
            >
              {columns.map((column) => (
                <AccordionItem key={column.title} value={column.title}>
                  <AccordionTrigger className="w-full py-4 text-left">
                    <div className="flex w-full items-center justify-between">
                      <span className="text-lg font-bold">{column.title}</span>
                      <Plus
                        className="size-4 shrink-0 text-foreground transition-transform duration-300 group-data-expanded:rotate-45"
                        aria-hidden="true"
                      />
                    </div>
                  </AccordionTrigger>
                  <AccordionContent>
                    <div className="pb-6">
                      <ColumnLinks column={column} />
                    </div>
                  </AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          </div>

          <p className="mt-6 hidden max-w-80 text-sm leading-relaxed text-muted-foreground xl:mt-10 xl:block">
            Nyx UI is built with accessibility and developer experience in mind,
            every component is themeable, composable, and ships with full
            TypeScript support.
          </p>
        </div>

        {/* Desktop link columns */}
        <div className="mb-24 hidden flex-1 flex-row justify-between gap-12 xl:flex">
          {columns.map((column) => (
            <nav key={column.title} aria-label={column.title}>
              <h3 className="mb-3 text-lg font-bold">{column.title}</h3>
              <ColumnLinks column={column} />
            </nav>
          ))}
        </div>
      </div>

      {/* Big wordmark */}
      <div className="mb-8 mt-8 lg:mt-4 flex w-full">
        <p
          className="w-full bg-linear-to-b from-foreground/25 to-foreground/2 bg-clip-text text-center text-[18vw] leading-[0.8] font-black tracking-tighter text-transparent select-none xl:text-[13vw]"
          aria-hidden="true"
        >
          NYX UI
        </p>
      </div>

      {/* Bottom bar */}
      <div className="flex flex-col justify-between gap-6 xl:flex-row xl:items-center">
        <div className="hidden gap-6 xl:flex">
          {legalLinks.map((link) => (
            <Link
              key={link.label}
              href={link.href}
              className={cn(
                linkClass,
                "text-muted-foreground/70 hover:text-foreground",
              )}
            >
              {link.label}
            </Link>
          ))}
        </div>
        <div className="flex flex-1 flex-col justify-center w-full gap-6 sm:flex-row items-center sm:gap-0 xl:justify-end">
          <p className="text-sm text-muted-foreground/70">
            © {new Date().getFullYear()} Nyx UI. All rights reserved.
          </p>
          <div className="flex gap-6 sm:ml-6 xl:ml-0">
            {legalLinks.map((link) => (
              <Link
                key={link.label}
                href={link.href}
                className={cn(
                  linkClass,
                  "text-muted-foreground/70 hover:text-foreground xl:hidden",
                )}
              >
                {link.label}
              </Link>
            ))}
          </div>
        </div>
      </div>
    </footer>
  );
};

function ColumnLinks({ column }: { column: FooterColumn }) {
  return (
    <ul className="flex flex-col gap-6 pb-6 sm:pb-10 xl:gap-5 xl:pb-0">
      {column.groups.map((group, groupIndex) => (
        <li key={group.heading ?? groupIndex}>
          {group.heading && (
            <p className="mb-1 text-sm font-medium">{group.heading}</p>
          )}
          <ul className="flex flex-col gap-3 xl:gap-2">
            {group.links.map((link) => (
              <li key={link.label}>
                <Link href={link.href} className={linkClass}>
                  {link.label}
                </Link>
              </li>
            ))}
          </ul>
        </li>
      ))}
    </ul>
  );
}

"use client";
import {
  motion,
  AnimatePresence,
  Transition,
  Variants,
  Variant,
  MotionConfig,
} from "motion/react";
import { cn } from "@/lib/utils";
import React, { createContext, useContext, useState, ReactNode } from "react";

export type AccordionContextType = {
  expandedValue: React.Key | null;
  toggleItem: (value: React.Key) => void;
  variants?: { expanded: Variant; collapsed: Variant };
};

const AccordionContext = createContext<AccordionContextType | undefined>(
  undefined,
);

function useAccordion() {
  const context = useContext(AccordionContext);
  if (!context) {
    throw new Error("useAccordion must be used within an AccordionProvider");
  }
  return context;
}

export type AccordionProviderProps = {
  children: ReactNode;
  variants?: { expanded: Variant; collapsed: Variant };
  expandedValue?: React.Key | null;
  onValueChange?: (value: React.Key | null) => void;
};

function AccordionProvider({
  children,
  variants,
  expandedValue: externalExpandedValue,
  onValueChange,
}: AccordionProviderProps) {
  const [internalExpandedValue, setInternalExpandedValue] =
    useState<React.Key | null>(null);

  const expandedValue =
    externalExpandedValue !== undefined
      ? externalExpandedValue
      : internalExpandedValue;

  const toggleItem = (value: React.Key) => {
    const newValue = expandedValue === value ? null : value;
    if (onValueChange) {
      onValueChange(newValue);
    } else {
      setInternalExpandedValue(newValue);
    }
  };

  return (
    <AccordionContext.Provider value={{ expandedValue, toggleItem, variants }}>
      {children}
    </AccordionContext.Provider>
  );
}

export type AccordionProps = {
  children: ReactNode;
  className?: string;
  transition?: Transition;
  variants?: { expanded: Variant; collapsed: Variant };
  expandedValue?: React.Key | null;
  onValueChange?: (value: React.Key | null) => void;
};

function Accordion({
  children,
  className,
  transition,
  variants,
  expandedValue,
  onValueChange,
}: AccordionProps) {
  return (
    <MotionConfig transition={transition}>
      <div className={cn("relative", className)} aria-orientation="vertical">
        <AccordionProvider
          variants={variants}
          expandedValue={expandedValue}
          onValueChange={onValueChange}
        >
          {children}
        </AccordionProvider>
      </div>
    </MotionConfig>
  );
}

export type AccordionItemProps = {
  value: React.Key;
  children: ReactNode;
  className?: string;
};

interface AccordionChildProps {
  value?: React.Key;
  expanded?: boolean;
  [key: string]: unknown;
}

function AccordionItem({ value, children, className }: AccordionItemProps) {
  const { expandedValue } = useAccordion();
  const isExpanded = expandedValue === value;

  return (
    <div
      className={cn("nyxui-accordion-item", className)}
      {...(isExpanded ? { "data-expanded": "" } : { "data-closed": "" })}
    >
      {React.Children.map(children, (child) => {
        if (React.isValidElement<AccordionChildProps>(child)) {
          return React.cloneElement(child, {
            ...child.props,
            value,
            expanded: isExpanded,
          });
        }
        return child;
      })}
    </div>
  );
}

export type AccordionTriggerProps = {
  children: ReactNode;
  className?: string;
};

function AccordionTrigger({
  children,
  className,
  ...props
}: AccordionTriggerProps) {
  const { toggleItem, expandedValue } = useAccordion();
  const value = (props as { value?: React.Key }).value;
  const isExpanded = value === expandedValue;

  return (
    <button
      onClick={() => value !== undefined && toggleItem(value)}
      aria-expanded={isExpanded}
      type="button"
      className={cn("group", className)}
      {...(isExpanded ? { "data-expanded": "" } : { "data-closed": "" })}
    >
      {children}
    </button>
  );
}

export type AccordionContentProps = {
  children: ReactNode;
  className?: string;
};

function AccordionContent({
  children,
  className,
  ...props
}: AccordionContentProps) {
  const { expandedValue, variants } = useAccordion();
  const value = (props as { value?: React.Key }).value;
  const isExpanded = value === expandedValue;

  const BASE_VARIANTS: Variants = {
    expanded: { height: "auto", opacity: 1 },
    collapsed: { height: 0, opacity: 0 },
  };

  const combinedVariants = {
    expanded: { ...BASE_VARIANTS.expanded, ...variants?.expanded },
    collapsed: { ...BASE_VARIANTS.collapsed, ...variants?.collapsed },
  };

  return (
    <AnimatePresence initial={false}>
      {isExpanded && (
        <motion.div
          initial="collapsed"
          animate="expanded"
          exit="collapsed"
          variants={combinedVariants}
          className={className}
        >
          {children}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };
